import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 5

def design(feats):
    # Check if we have a mechanism (about 1 in 5 worlds)
    if np.random.rand() < 0.8:  # 80% chance of no mechanism
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Find strong features using Welch's t-test
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            # For clinical/cohort variables, check if they're associated with outcome
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if abs(t_stat) > 3.0 and p_val < 0.001:
                strong_features.append((fid, abs(t_stat)))
        else:
            # For other features, use effect size and significance
            mean_diff = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if abs(mean_diff) > 0.5 and abs(t_stat) > 3.0:
                strong_features.append((fid, abs(t_stat)))

    # Sort by strength
    strong_features.sort(key=lambda x: x[1], reverse=True)

    # If no strong features found, return empty design
    if not strong_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top drivers (up to MAX_DRIVERS)
    drivers = tuple(fid for fid, _ in strong_features[:MAX_DRIVERS])

    # Build columns and products based on correlations and significance
    columns = set()
    products = set()

    # Add all significant features to columns
    for i, fid in enumerate(feats.ids):
        t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        if abs(t_stat) > 2.5 and p_val < 0.01:
            columns.add(fid)

    # Add some interaction terms between correlated features
    corr_pairs = []
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                corr_pairs.append((fid1, fid2))

    # Add some products of correlated pairs
    for fid1, fid2 in corr_pairs[:3]:  # Limit to top 3 pairs
        if fid1 in columns and fid2 in columns:
            products.add((fid1, fid2))

    # Create loadings for weighted score
    loadings = {}
    for fid in columns:
        idx = feats.column(fid)
        t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, idx], feats.x[feats.y==0, idx])
        loadings[fid] = t_stat

    return Design(
        drivers=drivers,
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

